mapper.select:

where del_flag = '0'
and type = #{machineType}
and spec_dimension = #{specDimension}
and carcass_both_layer = #{carcassBothLayer}
and reinforce = #{reinforce}
and tire_type = #{tireType}
and section_width_minimum = #{sectionWidthMinimum}
and section_width_maximum = #{sectionWidthMaximum}
and two_person_quota = #{twoPersonQuota}
and one_person_quota = #{onePersonQuota}
and remark = #{remark}

    order by create_time desc


    order by ${orderStr}


where del_flag = '0' and type = #{machineType,jdbcType=VARCHAR}
and spec_dimension = #{specDimension,jdbcType=DOUBLE}
AND carcass_both_layer = #{carcassBothLayer,jdbcType=DOUBLE}
AND reinforce = #{reinforce,jdbcType=VARCHAR}
AND tire_type = #{tireType,jdbcType=VARCHAR}
AND
(
section_width_minimum BETWEEN #{sectionWidthMinimum,jdbcType=DOUBLE} AND #{sectionWidthMaximum,jdbcType=DOUBLE}
OR section_width_maximum BETWEEN #{sectionWidthMinimum,jdbcType=DOUBLE} AND #{sectionWidthMaximum,jdbcType=DOUBLE}
OR (section_width_minimum  <=  #{sectionWidthMinimum,jdbcType=DOUBLE} AND section_width_maximum  >= 
#{sectionWidthMaximum,jdbcType=DOUBLE} )
)
AND id != #{id}
